import{_ as a,o as r,c as t,a6 as n}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"为什么 SSR 必须缓存 · 渲染一次，服务千次","description":"SSR 每个请求都要现算 HTML——这很贵。缓存的本质，是让「渲染一次的结果」被复用千次万次。这一章讲清缓存为何是 SSR 的命门、缓存的分层结构，以及那条贯穿始终的「新鲜度 vs 扛量」权衡。","frontmatter":{"title":"为什么 SSR 必须缓存 · 渲染一次，服务千次","description":"SSR 每个请求都要现算 HTML——这很贵。缓存的本质，是让「渲染一次的结果」被复用千次万次。这一章讲清缓存为何是 SSR 的命门、缓存的分层结构，以及那条贯穿始终的「新鲜度 vs 扛量」权衡。","source":"https://daiw.org/manual/ssr/why-cache"},"headers":[],"relativePath":"manual/computer-programming/ssr/why-cache.md","filePath":"manual/computer-programming/ssr/why-cache.md"}'),o={name:"manual/computer-programming/ssr/why-cache.md"};function e(l,s,i,c,g,p){return r(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="为什么-ssr-必须缓存-·-渲染一次-服务千次" tabindex="-1">为什么 SSR 必须缓存 · 渲染一次，服务千次 <a class="header-anchor" href="#为什么-ssr-必须缓存-·-渲染一次-服务千次" aria-label="Permalink to &quot;为什么 SSR 必须缓存 · 渲染一次，服务千次&quot;">​</a></h1><p>SSR 每个请求都要现算 HTML——这很贵。缓存的本质，是让「渲染一次的结果」被复用千次万次。这一章讲清缓存为何是 SSR 的命门、缓存的分层结构，以及那条贯穿始终的「新鲜度 vs 扛量」权衡。</p><p>我们正式进入本专栏的重点。开篇先把最重要的直觉钉牢：</p><blockquote><p><strong>SSR 的本质是「每请求现算」，而缓存的本质是「算一次、用很多次」。</strong> 没有缓存的 SSR，几乎无法上规模。</p></blockquote><p><a href="/Front2Full/manual/computer-programming/ssr/what-is-ssr">SSR 那章</a> 说过：每一个请求，服务器都要查库、调 API、把组件渲染成 HTML 字符串。假设渲染一个页面要 50ms CPU——一个请求还好，可当这个页面每秒被访问 2000 次，服务器每秒就要花 100 秒的 CPU 去渲染。<strong>渲染开销随流量线性增长，服务器很快就被自己压垮。</strong></p><p>缓存改变了这个算式：<strong>把渲染好的结果存起来，后续请求直接拿现成的，根本不再触发渲染。</strong> 一次渲染的成果，可以服务成千上万个请求。这就是缓存对 SSR 的意义——它不是「优化项」，而是<strong>让 SSR 在生产环境可用的前提</strong>。</p><h2 id="命中与未命中-一切的分水岭" tabindex="-1">命中与未命中：一切的分水岭 <a class="header-anchor" href="#命中与未命中-一切的分水岭" aria-label="Permalink to &quot;命中与未命中：一切的分水岭&quot;">​</a></h2><p>缓存世界里最重要的两个词：</p><ul><li><strong>命中(hit)</strong>：请求要的东西缓存里有，直接返回。<strong>快、几乎零成本。</strong></li><li><strong>未命中(miss)</strong>：缓存里没有，只能老老实实去<strong>现算一遍</strong>（触发完整 SSR），再把结果存进缓存。<strong>慢、贵。</strong></li></ul><p>于是<strong>缓存的全部目标，就是尽可能提高命中率(hit ratio)</strong>。命中率 99% 意味着 100 个请求里只有 1 个真的触发了渲染，其余 99 个都是从缓存里秒回的——服务器的渲染压力直接降到 1%。命中率从 90% 提到 99%，不是「好一点」，是渲染负载<strong>降为原来的十分之一</strong>。</p><h2 id="缓存是分层的" tabindex="-1">缓存是分层的 <a class="header-anchor" href="#缓存是分层的" aria-label="Permalink to &quot;缓存是分层的&quot;">​</a></h2><p>缓存不是一个东西，而是<strong>一串关卡</strong>。一个请求从用户出发，会依次经过多层缓存，<strong>在任何一层命中，就不必再往后走</strong>——尤其是不必走到最贵的那一步：源站现算。</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  U[&quot;用户请求&quot;] --&gt; B[&quot;① 浏览器缓存&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt;|&quot;未命中&quot;| C[&quot;② CDN / 边缘缓存&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt;|&quot;未命中&quot;| A[&quot;③ 应用 / 数据缓存&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A --&gt;|&quot;未命中&quot;| O[&quot;④ 源站:现算 SSR(贵)&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li><strong>① 浏览器缓存</strong>：用户自己电脑上的缓存。命中的话，请求<strong>根本没离开设备</strong>，最快。</li><li><strong>② CDN / 边缘缓存</strong>：离用户最近的 CDN 节点。命中的话，请求<strong>没到你的服务器</strong>——这是保护源站最关键的一层，后面<a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">专门讲</a>。</li><li><strong>③ 应用 / 数据缓存</strong>：你服务器内部的缓存（Redis、内存、框架的数据缓存）。渲染时要的数据命中这里，就省掉查库 / 调 API。</li><li><strong>④ 源站现算</strong>：全都没命中，才真正跑一次完整 SSR。<strong>这是你最想避免触发的一步。</strong></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>记住这个「关卡」心智：<strong>每往后一层，成本高一个数量级。</strong> 浏览器命中 ≈ 免费；CDN 命中 ≈ 一次就近网络读取；应用缓存命中 ≈ 省掉数据库；源站现算 ≈ 全套开销。<strong>缓存优化的艺术，就是让尽可能多的请求在尽可能靠前的关卡就被拦下。</strong> 后面几章会逐层展开：HTTP 头（浏览器）、CDN（边缘）、数据缓存（应用）。</p></div><h2 id="缓存缓存的到底是什么" tabindex="-1">缓存缓存的到底是什么 <a class="header-anchor" href="#缓存缓存的到底是什么" aria-label="Permalink to &quot;缓存缓存的到底是什么&quot;">​</a></h2><p>「缓存」在 SSR 语境里，其实指两类不同的东西，别混：</p><ul><li><strong>整页 HTML 缓存(full-page / route cache)</strong>：把<strong>渲染好的整份 HTML</strong> 存起来。命中时直接吐 HTML，连渲染都省了。最省，但只适合「对所有人一样」的页面。</li><li><strong>数据缓存(data cache)</strong>：缓存的不是 HTML，而是渲染时要用的<strong>数据</strong>（某个 API 的返回、某次查询的结果）。命中时仍要渲染，但省掉了取数。适合「HTML 因人而异、但底层数据可共享」的场景。</li></ul><p>这两类对应不同的层、解决不同的问题，后面都有专章。现在你只要知道：<strong>「缓存 HTML」和「缓存数据」是两把不同的刀。</strong></p><h2 id="绕不开的权衡-新鲜度-vs-扛量" tabindex="-1">绕不开的权衡：新鲜度 vs 扛量 <a class="header-anchor" href="#绕不开的权衡-新鲜度-vs-扛量" aria-label="Permalink to &quot;绕不开的权衡：新鲜度 vs 扛量&quot;">​</a></h2><p><a href="/Front2Full/manual/computer-programming/ssr/rendering-spectrum">渲染光谱那章</a> 提过的核心矛盾，在缓存这里变成了最日常的决策：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>缓存的每一个好处，都是用「一点点不新鲜」换来的。</strong></p><p>你把一份渲染结果缓存 60 秒——这 60 秒内，哪怕源数据变了，用户看到的还是旧的。你换来了这 60 秒内<strong>近乎无限的扛量</strong>（全走缓存），代价是<strong>最多 60 秒的陈旧</strong>。缓存时间(TTL)越长，越省、越能扛，但越可能给用户看旧数据；越短，越新鲜，但命中率越低、越常触发昂贵的渲染。</p><p><strong>缓存的全部功夫，就是在「能容忍多旧」和「想省多少」之间，为每一类内容找到那个甜点。</strong> 一个每周更新的博客，缓存一小时都嫌短；一个秒级变动的股价，缓存 5 秒都嫌长。没有万能 TTL，只有「这个内容能容忍多旧」。</p></div><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>SSR 每请求现算、开销随流量线性涨，缓存用「算一次、用很多次」破了这个局。缓存是<strong>分层的关卡</strong>（浏览器 → CDN → 应用 → 源站），越靠前越省；缓存的对象分<strong>整页 HTML</strong> 和<strong>数据</strong>两类；而所有缓存决策都逃不开<strong>新鲜度 vs 扛量</strong>的权衡。</p><p>理解了「为什么」，接下来逐层攻破「怎么做」。第一层、也是一切缓存的基石，是 <strong>HTTP 协议本身的缓存机制</strong>——服务器靠一个 <code>Cache-Control</code> 响应头，就能指挥浏览器和 CDN 怎么缓存。下一章从零讲透它。👉 <a href="/Front2Full/manual/computer-programming/ssr/http-caching">HTTP 缓存基石：Cache-Control 全家桶</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] MDN.「HTTP caching.」<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching</a> —— 缓存分层与命中概念。</li><li>[2] web.dev.「Love your cache.」<a href="https://web.dev/articles/love-your-cache" target="_blank" rel="noreferrer">https://web.dev/articles/love-your-cache</a> —— 缓存对性能与成本的意义。</li><li>[3] Cloudflare.「What is a CDN cache? Cache hit ratio.」<a href="https://www.cloudflare.com/learning/cdn/what-is-caching/" target="_blank" rel="noreferrer">https://www.cloudflare.com/learning/cdn/what-is-caching/</a> —— 命中率与分层缓存。</li></ul>`,27)])])}const d=a(o,[["render",e]]);export{u as __pageData,d as default};
